-- Post-migration catalog checks (run after each approved group)
-- STATE: PREPARED_NOT_APPLIED (2026-10-29). Generated from the live pg_index catalog; PostgreSQL 18, db legal_ai_db.
-- V2 supersedes V1 (20261029_duplicate_index_consolidation_v1.sql, unmodified) and the 2026-10-13 DROP_DRAFT (scan-count keepers).
-- Keeper rule: constraint/PK > name used by repo scripts (they CREATE IF NOT EXISTS or verify by name) > declared in the active Drizzle schema > declared only in drizzle/schema.ts (introspection snapshot) > name. idx_scan is NOT used (stats_reset unknown).
-- 1) dropped names gone; 2) keepers valid; 3) no INVALID indexes left behind.
-- Expect zero rows for applied groups (rows for not-yet-applied groups show as still_present).
WITH dropped(n) AS (VALUES ('idx_atlas_projection_outbox_aggregate'),('graphify_files_code_source_revision_idx_v2'),('idx_atlas_packet_features_packet_key'),('idx_atlas_packets_source_ref_idx'),('idx_atlas_packets_domain_class_idx'),('idx_atlas_packets_tags_gin'),('idx_atlas_packets_community_id_idx'),('idx_atlas_packets_packet_key_idx'),('idx_atlas_packets_som_index_idx'),('idx_atlas_packets_feature_id_idx'),('idx_summary_layers_packet_key'),('cluster_cards_centroid_dim_idx'),('idx_cluster_summaries_tags_gin'),('idx_code_features_page_rank_score'),('idx_codebase_chunk_semantic_tags_gin'),('idx_codebase_chunk_metadata_gin'),('feature_packet_bindings_source_ref_idx'),('feature_packet_bindings_packet_idx'),('rag_query_log_query_hash_idx'),('nes_chrom_packets_feature_ids_gin'),('nes_chrom_packets_metadata_gin'),('idx_nes_chrom_packets_feature_id_idx'),('nes_chrom_packets_feature_id_idx'),('nes_chrom_packets_lane_ids_gin'),('idx_nes_chrom_packets_source_ref_idx'),('nes_chrom_packets_source_ref_idx'),('nes_chrom_packets_tags_gin'),('nes_chrom_packets_kmeans_cluster_idx'),('nes_chrom_packets_som_index_idx'),('idx_route_runtime_packets_source_ref_idx'),('idx_task_semantic_packets_metadata_gin'),('idx_task_semantic_packets_packet_key_idx')),
     keepers(n) AS (VALUES ('atlas_projection_outbox_aggregate_idx'),('graphify_files_code_source_revision_compat_v1'),('idx_ast_packet_key'),('idx_atlas_packets_source_ref'),('idx_atlas_packets_domain_class'),('idx_atlas_packets_tags'),('idx_atlas_packets_community_id'),('idx_atlas_packets_packet_key'),('idx_atlas_packets_som_index'),('idx_atlas_packets_feature_id'),('idx_atlas_summary_layers_packet_key'),('cluster_cards_centroid_dim'),('cluster_summaries_tags_gin'),('idx_code_features_page_rank'),('codebase_chunk_index_semantic_tags_gin'),('codebase_chunk_index_metadata_gin'),('feature_packet_bindings_source_idx'),('feature_packet_bindings_packet_key_idx'),('rag_query_log_hash_idx'),('idx_nes_chrom_packets_feature_ids_gin'),('idx_nes_chrom_packets_metadata_gin'),('idx_nes_chrom_packets_feature_id'),('idx_nes_chrom_packets_lane_ids_gin'),('idx_nes_chrom_packets_source_ref'),('idx_nes_chrom_packets_tags_gin'),('idx_nes_chrom_packets_kmeans_cluster_idx'),('idx_nes_chrom_packets_som_index_idx'),('idx_route_runtime_packets_source_ref'),('idx_task_semantic_packets_metadata'),('idx_task_semantic_packets_packet_key'))
SELECT 'still_present' AS check_name, d.n FROM dropped d JOIN pg_class c ON c.relname=d.n AND c.relkind='i'
UNION ALL SELECT 'keeper_missing_or_invalid', k.n FROM keepers k LEFT JOIN pg_class c ON c.relname=k.n LEFT JOIN pg_index i ON i.indexrelid=c.oid WHERE c.oid IS NULL OR NOT i.indisvalid
UNION ALL SELECT 'invalid_index_anywhere', indexrelid::regclass::text FROM pg_index WHERE NOT indisvalid;
